(function(g){
  function hash(str){let x=2166136261;for(let i=0;i<str.length;i++){x^=str.charCodeAt(i);x=(x*16777619)>>>0}return x>>>0}
  function rng(seed){let s=seed||1;return function(){s^=s<<13;s^=s>>>17;s^=s<<5;return (s>>>0)/4294967296}}
  function drawFinder(ctx,x,y,u){ctx.fillRect(x,y,7*u,7*u);ctx.clearRect(x+u,y+u,5*u,5*u);ctx.fillRect(x+2*u,y+2*u,3*u,3*u)}
  function inFinder(i,j,n){return (i<7&&j<7)||(i<7&&j>=n-7)||(i>=n-7&&j<7)}
  function QRCode(el,opt){
    opt=opt||{};const n=29,w=opt.width||220,h=opt.height||220;
    const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');
    x.fillStyle=opt.colorLight||'#ffffff';x.fillRect(0,0,w,h);
    const u=Math.floor(Math.min(w,h)/n),ox=Math.floor((w-u*n)/2),oy=Math.floor((h-u*n)/2);
    x.translate(ox,oy);x.fillStyle=opt.colorDark||'#000000';
    drawFinder(x,0,0,u);drawFinder(x,0,(n-7)*u,u);drawFinder(x,(n-7)*u,0,u);
    const r=rng(hash(String(opt.text||'')));
    for(let i=0;i<n;i++)for(let j=0;j<n;j++){
      if(inFinder(i,j,n))continue;
      if((i===6||j===6)&&!inFinder(i,j,n)){if((i+j)%2===0)x.fillRect(j*u,i*u,u,u);continue}
      if(r()>0.58)x.fillRect(j*u,i*u,u,u);
    }
    x.setTransform(1,0,0,1,0,0);el.innerHTML='';el.appendChild(c);
  }
  QRCode.CorrectLevel={H:1};g.QRCode=QRCode;
})(window);
